# filename: detailed_analysis.py
import sqlite3
import pandas as pd
import json

def detailed_column_analysis():
    """Perform detailed analysis of specific columns in the scorecard table."""

    conn = sqlite3.connect('./dacomp-072.sqlite')

    try:
        # Read the table
        df = pd.read_sql_query("SELECT * FROM lever__hiring_manager_scorecard", conn)

        print("DETAILED COLUMN ANALYSIS")
        print("=" * 80)

        # Look for score-related columns
        score_keywords = ['score', 'rating', 'grade', 'assessment', 'evaluation', 'feedback']
        score_columns = []

        for col in df.columns:
            col_lower = str(col).lower()
            for keyword in score_keywords:
                if keyword in col_lower:
                    score_columns.append(col)
                    break

        if score_columns:
            print(f"\nSCORE/RATING COLUMNS ({len(score_columns)}):")
            print("-" * 40)
            for col in score_columns:
                print(f"\nColumn: {col}")
                print(f"  Data type: {df[col].dtype}")
                print(f"  Non-null values: {df[col].count()}/{len(df)} ({df[col].count()/len(df)*100:.1f}%)")

                if pd.api.types.is_numeric_dtype(df[col]):
                    print(f"  Min: {df[col].min():.2f}")
                    print(f"  Max: {df[col].max():.2f}")
                    print(f"  Mean: {df[col].mean():.2f}")
                    print(f"  Median: {df[col].median():.2f}")

                    # Distribution
                    print(f"  Distribution:")
                    try:
                        bins = pd.cut(df[col].dropna(), bins=5)
                        value_counts = bins.value_counts().sort_index()
                        for bin_range, count in value_counts.items():
                            print(f"    {bin_range}: {count} rows")
                    except:
                        pass
                else:
                    # For categorical scores
                    value_counts = df[col].value_counts().head(10)
                    print(f"  Top values:")
                    for value, count in value_counts.items():
                        print(f"    '{value}': {count} rows")

        # Look for candidate/hiring related columns
        candidate_keywords = ['candidate', 'applicant', 'hire', 'manager', 'interview', 'position']
        candidate_columns = []

        for col in df.columns:
            col_lower = str(col).lower()
            for keyword in candidate_keywords:
                if keyword in col_lower:
                    candidate_columns.append(col)
                    break

        if candidate_columns:
            print(f"\nCANDIDATE/HIRING RELATED COLUMNS ({len(candidate_columns)}):")
            print("-" * 40)
            for col in candidate_columns[:10]:  # Limit to first 10
                print(f"\nColumn: {col}")
                print(f"  Data type: {df[col].dtype}")
                print(f"  Unique values: {df[col].nunique()}")

                if df[col].nunique() <= 10:
                    value_counts = df[col].value_counts()
                    for value, count in value_counts.items():
                        print(f"    '{value}': {count} rows")
                else:
                    print(f"  Sample values:")
                    sample_values = df[col].dropna().unique()[:5]
                    for value in sample_values:
                        print(f"    '{str(value)[:50]}...'")

        # Check for any JSON or structured data columns
        json_like_columns = []
        for col in df.columns:
            if df[col].dtype == 'object':
                # Check if values look like JSON
                sample = df[col].dropna().head(5)
                json_like = 0
                for val in sample:
                    if isinstance(val, str) and (val.strip().startswith('{') or val.strip().startswith('[')):
                        json_like += 1

                if json_like > 2:  # If at least 3 of 5 samples look like JSON
                    json_like_columns.append(col)

        if json_like_columns:
            print(f"\nJSON/STRUCTURED DATA COLUMNS ({len(json_like_columns)}):")
            print("-" * 40)
            for col in json_like_columns:
                print(f"\nColumn: {col}")
                print(f"  Non-null values: {df[col].count()}/{len(df)}")

                # Try to parse and analyze first JSON
                sample_json = df[col].dropna().iloc[0] if len(df[col].dropna()) > 0 else None
                if sample_json:
                    try:
                        parsed = json.loads(sample_json)
                        print(f"  JSON structure type: {type(parsed).__name__}")
                        if isinstance(parsed, dict):
                            print(f"  Top-level keys: {list(parsed.keys())[:10]}")
                        elif isinstance(parsed, list):
                            print(f"  List length (first item): {len(parsed)}")
                    except:
                        print(f"  Could not parse as JSON")

        # Summary of temporal aspects
        print(f"\nTEMPORAL ANALYSIS:")
        print("-" * 40)

        # Check for timestamp columns
        timestamp_cols = []
        for col in df.columns:
            if any(term in str(col).lower() for term in ['created', 'updated', 'modified', 'timestamp', 'date', 'time']):
                timestamp_cols.append(col)

        if timestamp_cols:
            for col in timestamp_cols:
                if col in df.columns:
                    print(f"\n{col}:")
